# Look at contiguous runs of 7s in each row
arr = [
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 7, 3, 3, 3, 7, 7, 7, 3, 3, 3, 7, 3, 3, 7],
    [7, 3, 3, 3, 3, 3, 3, 3, 3, 3, 7, 7, 7, 3, 7, 3, 3, 7, 3, 7, 7, 3, 3, 3],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 7, 3, 3, 7, 3, 7, 3, 3, 7, 7, 3, 3, 7, 7, 3],
    [7, 3, 3, 3, 7, 7, 7, 7, 7, 7, 3, 3, 7, 3, 7, 7, 3, 7, 7, 3, 3, 7, 3, 3],
    [7, 3, 3, 7, 3, 3, 3, 3, 7, 7, 3, 3, 7, 3, 7, 3, 7, 7, 7, 3, 3, 7, 3, 3],
    [3, 3, 3, 7, 3, 3, 3, 3, 7, 7, 3, 3, 7, 3, 7, 7, 7, 7, 7, 3, 3, 7, 3, 3],
    [3, 7, 3, 7, 3, 3, 3, 3, 7, 7, 3, 3, 7, 3, 7, 3, 3, 3, 7, 3, 3, 7, 7, 3],
    [3, 3, 3, 3, 7, 7, 7, 7, 3, 7, 7, 7, 7, 3, 3, 3, 3, 3, 7, 3, 3, 7, 3, 3],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 7, 7, 3, 3, 3, 3, 3, 7, 7, 7, 3, 3, 3]
]

def find_runs(row):
    runs = []
    current_run = None
    for i, v in enumerate(row):
        if v == 7 and not current_run:
            current_run = {'start': i, 'end': i}
        elif v == 7 and current_run:
            current_run['end'] = i
        else:
            if current_run:
                runs.append(current_run)
                current_run = None
    return runs

for i, r in enumerate(arr):
    runs = find_runs(r)
    if runs:
        total_sevens = sum(end - start + 1 for start, end in [(run['start'], run['end']) for run in runs])
        print(f"Row {i+1}: {len(runs)} runs, {total_sevens} 7s")
        if len(runs) == 1:
            print(f"  Single run from col {runs[0]['start']} to {runs[0]['end']}")
    else:
        print(f"Row {i+1}: No runs (all 3s)")

